// Typed Scala facade for tau2-bench domain 'telecom-workflow' — the FIXED, committed
// tool surface the agent calls. Generated by gen_tools.py; regenerate the
// committed facades after a tau2 upgrade with:  ./regen_facades.sh
// (which overwrites these files). Each function dispatches to the in-scope
// tau2 tool via Tau.callTool.

val facadeDomain: String = "telecom-workflow"

/** Per-domain prompt guidance — see facades/guidance/telecom-workflow.md. */
val domainGuidance: String =
  """- Follow the troubleshooting workflow steps IN ORDER; do not skip ahead or stop early.
- Identity: verify by phone number only; do NOT ask for date of birth (DOB is for name
  lookup only) — demanding it derails the customer.
- For ANY data/MMS issue you MUST call getDataUsage on the affected line; if
  data_used_gb >= data_limit_gb, call refuelData (after the customer agrees) before
  concluding. Never skip this account-side step.
- When the customer is travelling/abroad, after the device data-roaming toggle also check
  the line's roaming_enabled and call enableRoaming (free) if it is off — a required
  account-side step.
- Read tool results literally: compare data_used_gb to data_limit_gb (ignore
  data_refueling_gb); never report "within limit" without citing those exact numbers.
- Do NOT transferToHumanAgents until every relevant workflow step is done AND its
  account-side fix attempted — premature escalation is scored as a failure.
- Pass the bare id string to getCustomerById / getDetailsById (e.g. "C1001", "L1002") —
  never a JSON object or the whole lookup result."""

/** Finds a customer by their primary contact or line phone number. */
def getCustomerByPhone(phoneNumber: String): String =
  val args = ujson.Obj()
  args("phone_number") = ujson.Str(phoneNumber)
  Tau.callTool("get_customer_by_phone", args)

/** Retrieves a customer directly by their unique ID. */
def getCustomerById(customerId: String): String =
  val args = ujson.Obj()
  args("customer_id") = ujson.Str(customerId)
  Tau.callTool("get_customer_by_id", args)

/** Searches for customers by name and DOB. May return multiple matches if names are similar, DOB helps disambiguate. */
def getCustomerByName(fullName: String, dob: String): String =
  val args = ujson.Obj()
  args("full_name") = ujson.Str(fullName)
  args("dob") = ujson.Str(dob)
  Tau.callTool("get_customer_by_name", args)

/** Retrieves the details for a given ID. The ID must be a valid ID for a Customer, Line, Device, Bill, or Plan. */
def getDetailsById(id: String): String =
  val args = ujson.Obj()
  args("id") = ujson.Str(id)
  Tau.callTool("get_details_by_id", args)

/** Suspends a specific line (max 6 months). Checks: Line status must be Active. Logic: Sets line status to Suspended, records suspension_start_date. */
def suspendLine(customerId: String, lineId: String, reason: String): String =
  val args = ujson.Obj()
  args("customer_id") = ujson.Str(customerId)
  args("line_id") = ujson.Str(lineId)
  args("reason") = ujson.Str(reason)
  Tau.callTool("suspend_line", args)

/** Resumes a suspended line. Checks: Line status must be Suspended or Pending Activation. Logic: Sets line status to Active, clears suspension_start_date. */
def resumeLine(customerId: String, lineId: String): String =
  val args = ujson.Obj()
  args("customer_id") = ujson.Str(customerId)
  args("line_id") = ujson.Str(lineId)
  Tau.callTool("resume_line", args)

/** Retrieves a list of the customer's bills, most recent first. */
def getBillsForCustomer(customerId: String, limit: Option[Int] = None): String =
  val args = ujson.Obj()
  args("customer_id") = ujson.Str(customerId)
  limit.foreach(v => args("limit") = ujson.Num(v))
  Tau.callTool("get_bills_for_customer", args)

/** Sends a payment request to the customer for a specific bill. Checks: - Customer exists - Bill exists and belongs to the customer - No other bills are already awaiting payment for this customer Logic: Sets bill status to AWAITING_PAYMENT and notifies customer. Warning: This method does not check if the bill is already PAID. Always check the bill status before calling this method. */
def sendPaymentRequest(customerId: String, billId: String): String =
  val args = ujson.Obj()
  args("customer_id") = ujson.Str(customerId)
  args("bill_id") = ujson.Str(billId)
  Tau.callTool("send_payment_request", args)

/** Retrieves current billing cycle data usage for a line, including data refueling amount, data limit, and cycle end date. */
def getDataUsage(customerId: String, lineId: String): String =
  val args = ujson.Obj()
  args("customer_id") = ujson.Str(customerId)
  args("line_id") = ujson.Str(lineId)
  Tau.callTool("get_data_usage", args)

/** Enables international roaming on a line. */
def enableRoaming(customerId: String, lineId: String): String =
  val args = ujson.Obj()
  args("customer_id") = ujson.Str(customerId)
  args("line_id") = ujson.Str(lineId)
  Tau.callTool("enable_roaming", args)

/** Disables international roaming on a line. */
def disableRoaming(customerId: String, lineId: String): String =
  val args = ujson.Obj()
  args("customer_id") = ujson.Str(customerId)
  args("line_id") = ujson.Str(lineId)
  Tau.callTool("disable_roaming", args)

/** Transfer the user to a human agent, with a summary of the user's issue. Only transfer if - the user explicitly asks for a human agent - given the policy and the available tools, you cannot solve the user's issue. */
def transferToHumanAgents(summary: String): String =
  val args = ujson.Obj()
  args("summary") = ujson.Str(summary)
  Tau.callTool("transfer_to_human_agents", args)

/** Refuels data for a specific line, adding to the customer's bill. Checks: Line status must be Active, Customer owns the line. Logic: Adds data to the line and charges customer based on the plan's refueling rate. */
def refuelData(customerId: String, lineId: String, gbAmount: Double): String =
  val args = ujson.Obj()
  args("customer_id") = ujson.Str(customerId)
  args("line_id") = ujson.Str(lineId)
  args("gb_amount") = ujson.Num(gbAmount)
  Tau.callTool("refuel_data", args)

/** Call this function when you are done with the task. */
def done(): String = Tau.callTool("done")

